  "Datensatz ohne zusätzliche Filter öffnen": "Open the record without additional filters",
  "Datensatz-ID": "Record ID",
  "Datensatz, sämtliche Konten und ursprüngliche geschützte Quellen gelten gemeinsam. Eine Freigabe hebt andere notwendige Rechte nicht auf. Administratoren erhalten keinen stillen Inhaltszugriff.": "The record, all accounts and original protected sources apply together. One permission does not override other required rights. Administrators do not receive implicit access to content.",
