  "Datumsformat für dieses CSV-Profil ausdrücklich auswählen": "Explicitly select the date format for this CSV profile",
  "Datumsfristen werden sieben Tage vorher und am Fälligkeitstag ab 09:00 Uhr in der Haushaltszeitzone berücksichtigt. Jeder Hinweis bleibt 24 Stunden gültig. Frühere Friststufen werden nicht nachgeholt.": "Calendar deadlines are considered seven days before and on the due date from 09:00 in the household time zone. Each alert remains valid for 24 hours. Earlier reminder stages are not replayed.",
  "Datumsgrund": "Date reason",
  "Datumsgründe und relevante Chargenmengen (": "Date reasons and relevant batch quantities (",
  "Datumsprüfung erforderlich. Die Auswahl ist keine Empfehlung, abgelaufene Ware zu verwenden.": "Date review required. This selection is not a recommendation to use expired goods.",
  "Datumsprüfung erforderlich. Dieser Vorschlag wird nicht als dringende Verbrauchsempfehlung hervorgehoben.": "Date review required. This suggestion is not highlighted as an urgent consumption recommendation.",
  "Dauer · Sekunden": "Duration · seconds",
  "Dauer fehlt und wird nicht als null Minuten eingeplant": "Duration is missing and is not planned as zero minutes",
  "Dauer ist die eingetragene Vorbereitung plus Kochzeit. Null Minuten kann auch „nicht erfasst“ bedeuten. Kochdaten stammen nur aus abgeschlossenen Zubereitungen bis heute. Ergebnisse erscheinen vom zuletzt geänderten Rezept an.": "Duration is the entered preparation plus cooking time. Zero minutes may also mean “not recorded”. Cooking dates come only from completed preparations up to today. Results start with the most recently changed recipe.",
