  "Die Woche zuerst vollständig laden.": "First load the complete week.",
  "Die Zähldifferenz ist nicht als einzelne exakte Bestandsbewegung buchbar. Einheit und gezählten Bestand prüfen.": "The count difference cannot be posted as a single exact stock movement. Review the unit and counted stock.",
  "Die Zahlungserinnerung konnte nicht sicher gelesen werden. Bitte erneut laden.": "The payment reminder could not be read safely. Please reload.",
  "Die Zielmahlzeiten bleiben als ungeklärte Resteplanung erhalten. Es wird kein Vorrat verändert.": "The destination meals are retained as unresolved leftover plans. Stock is not changed.",
  "Die zu ersetzende Komponente gehört nicht mehr zu diesem Entwurf.": "The component to replace no longer belongs to this draft.",
  "Die zuletzt erfassten 64 Abschlüsse überschreiten das sichere Auswertungsbudget. Es wurden keine Teilvorschläge berechnet.": "The last 64 recorded completions exceed the safe analysis budget. No partial suggestions were calculated.",
