  "Diese Auswahl steuert deine Einkaufs-Gerätehinweise jetzt dauerhaft. Beim Ausschalten bleibt der frühere Listenversand aus; In-App-Hinweise und Listenfreigaben bleiben unabhängig davon erhalten.": "This selection now permanently controls your Shopping device notifications. Turning it off keeps the previous list delivery off; in-app notifications and list permissions remain independent.",
