  "Diese Auswertung unterstützt höchstens 10.000 Tankvorgänge. Es werden keine unvollständigen Ergebnisse angezeigt; für den vollständigen Datenbestand die Betreiber-Sicherung verwenden.": "This analysis supports up to 10,000 refueling entries. Incomplete results are not displayed; use the operator backup for the complete dataset.",
