  "Ein kurzer Ton gilt nur für diese sichtbare Sitzung. Hinweise, die mehr als eine Minute verspätet sind, lösen keinen neuen Ton aus. Für einen zwingend pünktlichen Alarm nutze zusätzlich den Gerätewecker.": "A short tone only applies to this visible session. Alerts more than a minute late do not trigger a new tone. If an alarm must ring on time, also use your device's alarm.",
  "Ein neuer Scan verwendet die ausgewählten Originalseiten in der angegebenen Reihenfolge. Für eine Teilung nur die gewünschten Seiten auswählen. Originale bleiben erhalten.": "A new scan uses the selected original pages in the specified order. To split a scan, select only the pages you want. Originals are retained.",
  "Ein neuer Tacho beginnt eine eigene Reihe. Tatsächlichen Abschlussstand und neuen Anfangsstand eintragen; ein Höchststand aus fremden Reihen wird nicht als aktueller Stand übernommen. Überlappungen und Buchungen am Wechseltag müssen ausdrücklich geprüft werden.": "A new odometer starts a separate series. Enter the actual closing reading and new initial reading; a maximum reading from another series is not used as the current reading. Overlaps and postings on the replacement date must be explicitly reviewed.",
