  "Ein Sicherheitshinweis für dein Konto ist verfügbar. Household öffnen.": "An account security notice is available. Open Household.",
  "Ein Teil der Übersicht ist nicht verfügbar. Die übrigen Bereiche sind aktuell.": "Part of the overview is unavailable. The other sections are up to date.",
  "Ein Treffer füllt ausschließlich das Eingabefeld. Keine Fotos werden gespeichert. Nach einer Minute stoppt die Kamera.": "A match only fills the input field. No photos are saved. The camera stops after one minute.",
  "Ein Überlauf der ausdrücklich hinterlegten Zählergrenze ist bestätigt": "A rollover at the explicitly recorded meter limit is confirmed",
  "Ein ungeprüfter Einkaufsartikel wurde ergänzt. Kein Einkauf wurde bestätigt.": "An unreviewed shopping item was added. No purchase was confirmed.",
  "Ein Verbrenner-Abschnitt beginnt und endet an tatsächlich dokumentierten Volltankungen derselben Reihe und Kraftstoffart. Fehlende Tankungen, uneindeutige Reihenfolgen und Zählerwechsel unterbrechen ihn. Ein älterer brauchbarer Abschnitt wird als historisch gekennzeichnet. Ladeenergie ist eine eigene Bilanz und keine stillschweigend umgerechnete Kraftstoffmenge.": "A combustion-fuel interval starts and ends at actual documented full refuellings within the same series and fuel type. Missing refuellings, ambiguous ordering and odometer replacements interrupt it. An older usable interval is marked as historical. Charging energy has its own balance and is not silently converted into a fuel quantity.",
  "Ein vollständiger Abgleich braucht alle tatsächlichen Positionspreise und die Belegsumme.": "A complete reconciliation requires all actual item prices and the receipt total.",
  "Ein Vorgang läuft bereits.": "An operation is already running.",
