  "Ein vorheriger Vorgang ist noch nicht bestätigt. Nur den Belegstatus abfragen; Eingaben und Prüftoken wurden nicht lokal gespeichert.": "A previous operation is still unconfirmed. Only check the receipt status; inputs and review tokens were not saved locally.",
