  "Eine CSV-Datei wird nur im aktuellen Browserformular und als privater serverseitiger Prüfauftrag verwendet. Die Übernahme erzeugt geprüfte Datensätze; sie verbindet sich nicht mit einer Bank.": "A CSV file is used only in the current browser form and as a private server-side review job. Applying it creates reviewed records; it does not connect to a bank.",
  "Eine Erinnerung gehört zu dieser Buchung. Sie bucht und überweist kein Geld.": "A reminder belongs to this entry. It does not book or transfer money.",
  "Eine erste Volltankung als Startpunkt fehlt.": "The first full refuelling needed as a starting point is missing.",
  "Eine fehlende EUR-Bewertung bleibt unbekannt. Ein tatsächlich unter einen EUR-Cent gerundeter Betrag bleibt mit seinem Original bestehen.": "A missing EUR valuation remains unknown. An amount actually rounded below one euro cent is retained with its original value.",
  "Eine fehlende Tankung unterbricht den Abschnitt.": "A missing refuelling interrupts the interval.",
  "Eine fehlende Tankung unterbricht die Mengenbilanz.": "A missing fill-up interrupts the quantity balance.",
  "Eine Freigabe ist ein geheimer Nur-Lese-Link, kein rollender Kalender. Jeder mit dem Link kann diese Woche lesen. Abmelden widerruft ihn nicht; Passwort- oder Berechtigungsänderungen können ihn ungültig machen.": "A share is a secret read-only link, not a rolling calendar. Anyone with the link can read this week. Signing out does not revoke it; password or permission changes may invalidate it.",
