  "Eine Komponente benötigt eine eindeutige Mahlzeit und Position": "A component requires a unique meal and position",
  "Eine Komponente wurde entfernt. Wähle ihre Quelle erneut oder entferne sie ausdrücklich aus deinem Entwurf.": "A component was removed. Select its source again or explicitly remove it from your draft.",
  "Eine Kopie kann Notizen, Zutaten, Schritte, Quelle, Nährwert- und Allergenbelege sowie höchstens zwei kleine Bilder enthalten. Bis zu 20 Rezepte, zusammen 5 MiB, höchstens 30 Tage. Kein aktueller Preis- oder Vorratsstand.": "A copy may contain notes, ingredients, steps, source, nutrition and allergen evidence and at most two small images. Up to 20 recipes, 5 MiB in total, for at most 30 days. No current prices or stock levels.",
