  "Eine manuell geschätzte Mahlzeit wurde entfernt. Den betreffenden alten Betrag leeren oder den Entwurf ausdrücklich verwerfen.": "A manually estimated meal was removed. Clear its old amount or explicitly discard the draft.",
  "Eine manuell portionierte Rezeptmahlzeit und Komponente auswählen.": "Select a recipe meal with manual servings and a component.",
