  "Eine Tageszusammenfassung verfällt spätestens um Mitternacht in dieser Zeitzone. Ruhezeiten verschieben sie nicht in den nächsten Tag.": "A daily summary expires no later than midnight in this time zone. Quiet hours do not carry it over into the next day.",
