  "Eine verknüpfte Aufgabe hat eigene Benachrichtigungen. Wenn du beide Kategorien erlaubst, können beide Hinweise erscheinen.": "A linked task has its own notifications. If you allow both categories, both alerts may appear.",
  "Eine vollständige Lesekopie einschließlich Artikelnotizen und angezeigter Zuständigkeiten wird unverschlüsselt auf diesem Gerät gespeichert. Keine gesonderten Preisfelder, Bilder oder Bearbeitungsanfragen; eigene Notizen können beliebige persönliche Angaben enthalten. Es wird nichts automatisch übertragen.": "A complete read-only copy, including item notes and displayed responsibilities, is stored unencrypted on this device. No separate price fields, images or editing requests; your own notes may contain any personal details. Nothing is transmitted automatically.",
