  "Erlaube Fahrzeuge hier und unten bei jedem gewünschten Gerät ausdrücklich vor der Frist. Die Zuständigkeit allein aktiviert keine Gerätehinweise.": "Explicitly allow Vehicles here and below on each chosen device before the deadline. Being responsible does not enable device notifications by itself.",
  "Erlaube Finanzhinweise hier und unten bei jedem gewünschten Gerät ausdrücklich. Eine bestätigte Fälligkeit oder Zuständigkeit allein aktiviert keine Gerätehinweise.": "Explicitly allow finance notifications here and below on each chosen device. A confirmed due date or responsibility alone does not enable device notifications.",
  "Erlaube Kochtimer hier und bei den gewünschten Geräten vor dem Timerstart. Spätere Freigaben holen laufende Timer nicht nach; starte sie bei Bedarf ausdrücklich neu.": "Allow cooking timers here and on your chosen devices before starting a timer. Later permission does not catch up running timers; deliberately restart them if needed.",
  "Erlaube Vorrat hier und unten bei jedem gewünschten Gerät ausdrücklich, bevor ein neuer Hinweis entsteht. Bestehende Geräte werden nicht automatisch freigegeben.": "Explicitly allow Pantry here and below on each chosen device before a new alert arises. Existing devices are not enabled automatically.",
  "Erlauben": "Allow",
  "Erlaubnis": "Permission",
  "Erlaubt ausdrücklich vorgemerkte Änderungen, eigene Scan-Entwürfe und bewusst gespeicherte Einkaufs-Lesekopien. Die Freigabe speichert von selbst keine Liste. Daten sind auf dem Gerät nicht verschlüsselt. Bei Abmeldung oder Entzug der Freigabe werden die privaten Offline-Bereiche geleert; eine fehlgeschlagene Löschung wird gemeldet.": "Allows explicitly queued changes, your scan drafts and deliberately saved shopping read-only copies. Enabling this does not save any list automatically. Device data is not encrypted. Signing out or revoking permission clears private offline areas; failed deletion is reported.",
  "Erlaubte Aktionen": "Allowed actions",
  "Erledigen: ": "Complete: ",
