  "Erledigt am": "Completed on",
  "Erledigte Artikel einlagern oder ausdrücklich ohne Vorrat abschließen; offene Artikel ausdrücklich auslassen": "Store completed items or explicitly finish without pantry storage; explicitly skip open items",
  "Erledigte Artikel zuerst wieder öffnen": "Reopen completed items first",
  "Erledigte oder aufgehobene Erinnerungen und belegte tatsächliche Zahlungen beenden offene Hinweise. Eine gebuchte Ausgabe allein ist noch keine belegte Zahlung. Änderungen an Buchung, Frist oder Zuständigkeit können eine erneute Bestätigung erfordern.": "Completed or cancelled reminders and recorded actual payments end pending alerts. A posted expense alone is not proof of payment. Changes to the entry, deadline or responsibility may require confirmation again.",
