  "Ersetzt": "Replaced",
  "ersetzt den gesamten gewählten vorhandenen Rezeptstand.": "replaces the entire selected existing recipe version.",
  "Ersetzung vorgemerkt. Die gemeinsame Simulation für alle Plätze erneut berechnen; bisherige Begründungen gelten noch für den alten Vorschlag.": "Replacement selected. Recalculate the combined simulation for all slots; previous explanations still apply to the old suggestion.",
  "Erst „Kamera starten“ fordert Zugriff an. Ein Treffer füllt nur das Barcode-Feld. Danach lokal nachschlagen und Produkt sowie Menge selbst prüfen. Nach einer Minute stoppt die Kamera.": "Only “Start camera” requests access. A match only fills the barcode field. Then look up locally and review the product and quantity yourself. The camera stops after one minute.",
