  "Erste Volltankung dokumentieren; Anfangsstände ersetzen sie nicht.": "Record the first full fill-up; opening readings do not replace it.",
  "Erste Zeile: Feldnamen. UUIDs für Beziehungen, Datum YYYY-MM-DD, Beträge als Euro-Text (z. B. 12,50). Maximal 500 Zeilen; Vorschau vor Übernahme.": "First row: field names. UUIDs for relationships, dates YYYY-MM-DD, amounts as euro text (e.g. 12.50). Maximum 500 rows; preview before applying.",
  "Ersteinrichtung": "Initial setup",
  "Erstellt": "Created",
  "Erstellt genau eine echte Ausgabe mit diesem bestätigten Betrag. Diese Übernahme ist unabhängig von der Verbrauchsschätzung.": "Creates exactly one actual expense with this confirmed amount. This application is independent of the consumption estimate.",
  "Erstellt unabhängige Artikel aus höchstens 500 Positionen. Erledigungen, Ersatzentscheidungen und Zuständigkeiten werden zurückgesetzt.": "Creates independent items from at most 500 entries. Completions, substitution decisions and responsibilities are reset.",
