  "Erstes Rezept anlegen": "Create first recipe",
  "Erwartete Reste ": "Expected leftovers ",
  "Erwartete Reste dürfen die bestehende Produktion nicht überschreiten.": "Expected leftovers must not exceed existing production.",
  "Erwartete Reste sind eine positive Teilmenge der bestehenden Produktion.": "Expected leftovers must be a positive portion of existing production.",
  "Erzeugung": "Generation",
  "Erzeugungsbeginn der Serie muss geprüft werden": "The series generation start must be reviewed",
  "Es erscheinen ausschließlich aktuell berechtigte Dokumente. Die Verknüpfung ändert keine Dokumentberechtigung. Anhänge am Fahrzeug und Dokumentverknüpfungen bleiben als Herkunft unterscheidbar.": "Only currently accessible documents are shown. Linking does not change document permissions. Vehicle attachments and document links remain distinguishable by their source.",
  "Es ist nur der minimale Vorgangsnachweis verfügbar.": "Only the minimal operation record is available.",
  "Es werden die 100 neuesten Freigaben angezeigt. Alle aktiven Freigaben stehen zuerst.": "The 100 most recent access grants are shown. All active grants appear first.",
  "Es wurde noch keine Änderung übernommen. Prüfe Werte, Quellen, Rundung und Auswirkungen.": "No change has been applied yet. Review values, sources, rounding and effects.",
  "Es zählt derselbe aktuell sichtbare vollständige Monat wie in der Budgetansicht, einschließlich Übertrag. Unvollständige Berechnungen und ein verfügbares Monatsbudget von null oder weniger lösen keine Prozenthinweise aus. Änderungen an Sichtbarkeit, Budget oder Monat beginnen mit einem neuen stillen Ausgangsstand.": "The calculation uses the same currently visible full month as the budget view, including carry-over. Incomplete calculations and a monthly allowance of zero or less do not trigger percentage alerts. Changes to visibility, the budget or month establish a new silent baseline.",
