  "Gerätehinweise haben einen unbekannten Konfigurationsstand.": "Device notifications have an unknown configuration state.",
  "Gerätehinweise können verspätet eintreffen oder ausbleiben, etwa bei fehlender Verbindung oder aktiviertem Fokusmodus. Für einen zwingend pünktlichen Kochalarm verwende zusätzlich den Gerätewecker.": "Device notifications can arrive late or fail to appear, for example without a connection or with Focus enabled. If a cooking alarm must ring on time, also use your device's alarm.",
