  "Gerätehinweise sind im Browser blockiert. Die Freigabe kann nur in den Browser-Einstellungen geändert werden.": "Device notifications are blocked in the browser. Permission can only be changed in browser settings.",
  "Gerätehinweise sind optional. Auf dem Sperrbildschirm stehen nur allgemeine Einkaufshinweise, keine Listen- oder Artikelnamen. Berechtigung und Serverregistrierung bestätigen keine tatsächliche Anzeige.": "Device notifications are optional. The lock screen shows only general shopping alerts, with no list or item names. Permission and server registration do not confirm actual display.",
