  "Je Charge eine genaue Basismenge, insgesamt höchstens 100 Chargen. Die Auswahl ersetzt die bisherige Reservierung dieser Mahlzeit vollständig. Mindesthaltbarkeit und Verbrauchshinweise bleiben gesondert zu prüfen.": "An exact base quantity per batch, with at most 100 batches in total. The selection fully replaces this meal's previous reservation. Best-before dates and consumption notices require separate review.",
  "Je Feld: Position behalten → Position dazugeben.": "Per field: keep item → add item.",
  "je Portion": "per serving",
  "Jede Bankzeile ausdrücklich übernehmen oder überspringen": "Explicitly import or skip each bank row",
  "Jede bestätigte Position ausdrücklich am Original prüfen": "Explicitly check each confirmed line item against the original",
  "Jede Buchung zählt an ihrem gespeicherten Tag in der Haushaltszeitzone. Verlust und Rücknahme werden getrennt summiert. Eine spätere Rücknahme kann den Nettowert eines Zeitraums negativ machen, wenn der ursprüngliche Verlust außerhalb des Zeitraums liegt. Es wird nichts auf null gekürzt.": "Each posting counts on its saved date in the household time zone. Losses and reversals are totalled separately. A later reversal may make a period's net amount negative if the original loss falls outside the period. Nothing is clamped to zero.",
  "Jede Dateizeile ausdrücklich entscheiden.": "Explicitly decide every file row.",
  "Jede Entwurfszeile braucht eine eindeutige Kennung": "Each draft row needs a unique identifier",
  "Jede gespeicherte Quellzutat ausdrücklich verbrauchen oder überspringen": "Explicitly consume or skip each saved source ingredient",
  "Jede gültige Quelle mit genau einer benannten Entscheidung bestätigen": "Confirm each valid source with exactly one named decision",
  "Jede Importzeile ausdrücklich übernehmen oder überspringen": "Explicitly import or skip each import row",
  "Jede Person zählt eine Portion. Eine manuelle Portionsmenge erhält die Teilnehmerauswahl. Gespeicherte inaktive Mitglieder bleiben sichtbar; ihre Kontodeaktivierung verändert keine Menge.": "Each person counts as one serving. A manual serving quantity retains the participant selection. Saved inactive members remain visible; disabling their account does not change quantities.",
  "Jede positive oder negative Zähldifferenz ausdrücklich begründen": "Explicitly explain every positive or negative count difference",
  "Jede Quelle nur einmal auswählen": "Select each source only once",
  "Jede Quellzutat genau einmal prüfen; Begründung auf 500 UTF-8-Bytes begrenzen": "Review each source ingredient exactly once; limit the reason to 500 UTF-8 bytes",
  "Jede tatsächlich vorhandene Belegseite höchstens einmal wählen": "Select each page of the actual receipt no more than once",
  "Jede verwendete Charge mit eindeutigem geprüftem Stand übermitteln": "Submit each used batch with a unique reviewed version",
  "Jede Zeile erstellt eine eigene neue Charge. Unvollständige Eingaben können als Entwurf gespeichert werden.": "Each row creates its own new batch. Incomplete entries can be saved as a draft.",
  "Jede Zeile wird einzeln gespeichert. Ein Gerätehinweis braucht sowohl deine persönliche als auch die Gerätefreigabe.": "Each row is saved separately. A device notification needs both your personal permission and permission for that device.",
  "Jede Zutat ausdrücklich prüfen. Es wurde noch nichts entnommen.": "Explicitly review every ingredient. Nothing has been withdrawn yet.",
  "Jeden Behälter eindeutig benennen und einen geprüften Lagerort auswählen": "Give each container a unique name and select a reviewed storage location",
  "Jeder bestätigte Änderungsvorgang erhält einen vollständigen Stand. Frühere Inhalte bleiben unverändert.": "Each confirmed change creates a complete version. Earlier content remains unchanged.",
  "Jeder mit dem geheimen Link kann Titel und Mahlzeitenart dieser sieben Tage für höchstens 90 Tage lesen. Abmelden widerruft die Freigabe nicht.": "Anyone with the secret link can read titles and meal types for these seven days for at most 90 days. Signing out does not revoke the share.",
  "Jedes Rezept wird einzeln mit dem aktuell freien Vorrat verglichen. Mehrere verfügbare Alternativen sind zusammen noch keine gedeckte Wochenplanung.": "Each recipe is individually compared with currently unreserved stock. Several available alternatives together do not yet constitute a covered weekly plan.",
  "Jedes übernommene Feld mit dem Originalbild vergleichen": "Compare every selected field with the original image",
