  "Kilometerfoto enthält ein nicht unterstütztes Feld": "The odometer photo contains an unsupported field",
  "Kilometerhinweise benötigen einen eindeutigen Stand aus der passenden Zählerreihe, der höchstens 30 Kalendertage alt ist. Zuerst muss nach deiner Freigabe ein Stand unter dem Ziel erkannt werden, danach ein Stand am oder über dem Ziel. Ein bereits erreichtes Ziel beim ersten Prüfen bleibt ohne Hinweis.": "Mileage alerts require an unambiguous reading from the matching odometer series, no more than 30 calendar days old. After you opt in, a reading below the target must first be observed, followed by a reading at or above it. A target already reached at the first check does not trigger an alert.",
