  "Nullbedarf wird ebenfalls gespeichert. Einkaufsabschluss und Einlagerung erfolgen anschließend in der Einkaufsliste. Physischer Vorrat wird durch diesen Abgleich nicht verändert.": "Zero demand is also saved. Checkout and adding to stock take place afterwards in the shopping list. This reconciliation does not change physical stock.",
  "Nummer bearbeiten": "Edit number",
  "Nur aktive Einkaufslisten abonnieren": "Only subscribe to active shopping lists",
  "Nur aktive Einkaufslisten können neu beobachtet werden.": "Only active shopping lists can be newly watched.",
  "Nur anhängen": "Append only",
  "Nur Artikel einer offenen Einkaufsliste zusammenführen": "Only merge items from an open shopping list",
  "Nur ausdrücklich ausgewählte Kopien auf diesem Gerät.": "Only explicitly selected copies on this device.",
  "Nur ausdrücklich ausgewählte Personen": "Explicitly selected people only",
  "Nur ausdrücklich gespeicherte Lesekopien dieses privaten Geräts. Kein Abhaken, Bearbeiten oder automatisches Übertragen. Die Kopien sind nicht verschlüsselt und können Artikelnotizen und angezeigte Zuständigkeiten enthalten.": "Only explicitly saved read-only copies on this private device. No checking off, editing or automatic transfer. Copies are not encrypted and may include item notes and displayed responsibilities.",
  "Nur ausdrücklich zugewiesene Personen erhalten Hinweise zu bestätigten Terminen. Teilnehmer und Ersteller werden nicht automatisch benachrichtigt.": "Only explicitly assigned people receive confirmed reminders. Participants and creators are not notified automatically.",
  "Nur deine eigenen laufenden Kochtimer werden gemeldet. Pause, Neustart, Bestätigung oder Sitzungsende entwerten alte Hinweise. Ein Push ist kein garantierter Wecker.": "Only your own running cooking timers are reported. Pausing, restarting, acknowledging or ending a session invalidates old alerts. Push is not a guaranteed alarm.",
  "Nur den Termin verschieben": "Only reschedule the occurrence",
  "Nur der angezeigte Reservierungsstand ": "Only the displayed reservation version ",
  "Nur der Fuelio-Tankabschnitt wird übernommen; andere Sicherungsabschnitte bleiben unverändert": "Only the Fuelio fill-up section is imported; other backup sections remain unchanged",
  "Nur der Vorgangsschlüssel wurde dauerhaft gesperrt. Die frühere Übernahme bleibt unbekannt.": "Only the operation key was permanently blocked. The result of the earlier application remains unknown.",
  "Nur die aktuell sichtbare Tabellenseite. Punkte folgen ihrer Reihenfolge. Grafische Höhen sind je Gruppe relativ skaliert und gerundet; Tabellenwerte bleiben exakt. ": "Only the currently visible table page. Points follow its order. Chart heights are scaled relatively and rounded within each group; table values remain exact. ",
  "Nur die ausdrücklich gewählten Seiten lokal erkennen · höchstens drei Seiten pro Aufruf. Weitere Seiten danach separat prüfen. Kein neuer Buchungseintrag wird erstellt.": "Recognize only the explicitly selected pages locally · Maximum three pages per request. Review further pages separately afterwards. No new posting is created.",
  "Nur die bestätigten leeren Plätze werden in einer Transaktion angelegt. Bestehende Mahlzeiten bleiben erhalten. Vorrat wird weder verbraucht noch reserviert.": "Only the confirmed empty slots are created in one transaction. Existing meals are retained. Stock is neither consumed nor reserved.",
  "Nur die gewählte Rezeptzeile wird vorbereitet. ": "Only the selected recipe row is prepared. ",
  "Nur die lokale übertragene Kopie löschen? Der Serverentwurf und Bestand bleiben erhalten.": "Delete only the local transferred copy? The server draft and stock are retained.",
  "Nur die Produktzuordnung dieser gespeicherten Plan-Zutat wird geändert. Rezept, Portionen, physischer Vorrat und Einkauf bleiben erhalten.": "Only the product assignment of this saved planning ingredient is changed. The recipe, servings, physical stock and shopping are retained.",
  "Nur die tatsächlich benötigten Modulversionen bestätigen": "Confirm only the module versions actually required",
