  "Nur für Administratoren. Benutzernamen zeigen die heutige Zuordnung. Die Suche prüft Benutzernamen und gespeicherte Datensatzbezeichnungen. Geschützte Felder zeigen eine Änderung, aber keinen Inhalt. Frühere Einträge enthalten gegebenenfalls keine Feldhistorie.": "Administrators only. Usernames show the current account association. Search checks usernames and stored record labels. Protected fields indicate a change without revealing their contents. Older entries may have no field history.",
  "Nur für Leistungsregister; mindestens sieben ausreichend abgedeckte Nächte.": "Only for power registers; at least seven nights with sufficient coverage.",
