  "nur HTTPS:443 ohne Zugangsdaten und Fragment ist zulässig": "Only HTTPS on port 443 without credentials or a fragment is allowed",
  "Nur im Arbeitsspeicher dieser geöffneten Ansicht. Nach dem Schließen lässt er sich nicht erneut anzeigen. Bei Verlust widerrufen und eine neue Freigabe erstellen.": "Only held in memory in this open view. After closing, it cannot be displayed again. If lost, revoke it and create a new share.",
  "nur JPEG, PNG und PDF zulässig": "Only JPEG, PNG and PDF are allowed",
  "Nur lokale Daten geprüft. Es wurde nichts ergänzt oder gekauft.": "Only local data checked. Nothing was added or purchased.",
  "Nur mir zugewiesene und von mir übernommene Termine": "Only occurrences assigned to or claimed by me",
  "Nur nach deiner Auswahl, solange der Browser es erlaubt.": "Only after your selection, while the browser permits it.",
  "Nur Name und Filterkriterien werden lokal gespeichert; keine Rezepte, Ergebnisse oder Notizen. Höchstens 20 Ansichten. Sie verschwinden beim Abmelden oder Kontowechsel und werden nicht synchronisiert.": "Only the name and filter criteria are saved locally; no recipes, results or notes. At most 20 views. They disappear on sign-out or account change and are not synchronised.",
  "nur öffentliche HTTPS-Quellen auf Port 443 sind zulässig": "Only public HTTPS sources on port 443 are allowed",
  "Nur online. Keine Finanzentwürfe werden in IndexedDB oder anderen privaten Gerätespeichern abgelegt. Der bisherige": "Online only. No financial drafts are stored in IndexedDB or other private device storage. The previous",
