  "Nur positives Restbudget": "Positive remaining budget only",
  "Nur Rezeptmahlzeiten enthalten Rezeptkomponenten": "Only recipe meals contain recipe components",
  "Nur tatsächlich abgeschlossene Einkäufe zählen. Ein Kaufabstand sagt weder Vorrat noch benötigte Menge voraus. Es wird nichts automatisch gekauft oder ergänzt.": "Only actually completed purchases count. A purchase interval predicts neither stock nor required quantity. Nothing is purchased or added automatically.",
  "Nur tatsächlich entsorgte Mengen buchen. Das Datum ist der heutige Buchungszeitpunkt; eine Rücknahme bleibt als eigener Beleg erhalten.": "Post only quantities actually discarded. The date is today's posting time; a reversal is retained as a separate record.",
