  "Verbrauch / 100 km": "Consumption / 100 km",
  "Verbrauch auf zwei Nachkommastellen gerundet.": "Consumption rounded to two decimal places.",
  "Verbrauch buchen": "Post consumption",
  "Verbrauch entsteht zwischen zwei tatsächlichen Volltankungen derselben Reihe und Kraftstoffart. Teilbetankungen dazwischen zählen mit; die erste Volltankung dient nur als Startpunkt. Fehlende Tankungen und uneindeutige Reihen oder Reihenfolgen werden erklärt. Ein älterer abgeschlossener Abschnitt bleibt als historisch gekennzeichnet. Verbrauchswerte werden auf zwei Nachkommastellen gerundet; Mengen und Strecken bleiben exakt.": "Consumption is calculated between two actual full refuellings within the same series and fuel type. Partial refuellings between them are included; the first full refuelling is only the starting point. Missing refuellings and ambiguous series or ordering are explained. An older completed interval remains marked as historical. Consumption values are rounded to two decimal places; quantities and distances remain exact.",
  "Verbrauch gespeichert. Vollständige Rücknahme eröffnet diesen Kochvorgang nicht erneut.": "Consumption saved. Fully reversing it does not reopen this cooking operation.",
