  "Verbrauchsdatum, Hinweis nach Öffnung und Mindesthaltbarkeit bleiben getrennte Angaben. Das früheste bekannte Datum bestimmt die Reihenfolge; Chargen ohne Datumsangabe stehen am Ende. Ein Öffnungshinweis ist eine hinterlegte Angabe und ersetzt kein Verbrauchsdatum.": "Use-by date, guidance after opening and best-before date remain separate details. The earliest known date determines the order; batches without dates come last. Opening guidance is recorded information and does not replace a use-by date.",
  "Verbrauchsdatum, MHD und Hinweise nach dem Öffnen werden getrennt angezeigt. Abgelaufene Verbrauchsdaten zählen nicht zur Deckung. Datumsangaben ersetzen keine Prüfung des Lebensmittels.": "Use-by dates, best-before dates and notices after opening are displayed separately. Past use-by dates do not count towards coverage. Dates do not replace checking the food itself.",
