  "Voraussetzung offen": "Prerequisite pending",
  "Voraussetzung öffnen": "Open prerequisite",
  "Voraussetzung: Modul pausiert, frische Anmeldung und geprüfte Sicherung. Eine Anforderung läuft nach 30 Minuten ab; der Betreiber führt sie über den Wartungsbefehl aus. Änderungen bleiben im Administrator-Protokoll nachvollziehbar.": "Requires a paused module, recent authentication and a verified backup. A request expires after 30 minutes; the operator runs it via the maintenance command. Changes remain traceable in the administrator audit log.",
  "Voraussetzungen": "Prerequisites",
  "Voraussetzungen müssen eindeutig und von der Aufgabe verschieden sein": "Prerequisites must be unique and different from the chore itself",
  "Voraussetzungen müssen für den jeweiligen Termin tatsächlich erledigt sein. Selbstbezug und Zyklen werden abgewiesen.": "Prerequisites must actually be completed for the relevant occurrence. Self-references and cycles are rejected.",
