  "Vorgaben": "Defaults",
  "Vorgaben & Plausibilität": "Defaults & plausibility",
  "Vorgaben erleichtern die nächste Eingabe. Plausibilitätsgrenzen erzeugen erklärte Hinweise und verändern keine Originalwerte. Kraftstoffmengen haben eine verbindliche Einheit; stille Umrechnungen zwischen Litern, Kilogramm und Kilowattstunden finden nicht statt.": "Defaults make the next entry easier. Plausibility limits produce explained notices and do not change original values. Fuel quantities have a mandatory unit; no silent conversion takes place between litres, kilograms and kilowatt-hours.",
  "Vorgaben sind eine Eingabehilfe. Prüfe Fahrzeug, Buchungsdatum und dafür passende Kilometerstandsreihe. Zwei Werte aus Menge, Einheitspreis und Betrag reichen für einen berechneten dritten Wert; die Rundung wird vor der Übernahme gezeigt.": "Defaults are an input aid. Check the vehicle, posting date and matching odometer series. Two of quantity, unit price and amount are enough to calculate the third value; rounding is shown before applying it.",
  "Vorgaben verwenden, Quelle prüfen und ausdrücklich bestätigen.": "Use defaults, check the source and confirm explicitly.",
